:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8a8fa8;
  --border: #2a2a4a;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}
.card {
  background: var(--card);
  border: 3px solid var(--border);
  border-radius: 0;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 8px 8px 0 rgba(0,0,0,0.4);
}
h1 {
  margin: 0 0 16px;
  font-size: 1.5rem;
  letter-spacing: 1px;
  text-transform: uppercase;
}
.counts {
  display: flex;
  gap: 24px;
  margin-bottom: 20px;
  font-size: 0.95rem;
  color: var(--muted);
}
.counts strong { color: var(--text); }
.input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
}
#todo-input {
  flex: 1;
  padding: 10px 12px;
  font-size: 1rem;
  background: var(--bg);
  border: 2px solid var(--border);
  color: var(--text);
  border-radius: 0;
  outline: none;
}
#todo-input:focus { border-color: var(--accent); }
#todo-add {
  width: 48px;
  font-size: 1.5rem;
  font-weight: bold;
  background: var(--accent);
  color: #fff;
  border: 2px solid var(--accent);
  border-radius: 0;
  cursor: pointer;
  transition: transform 0.05s;
}
#todo-add:hover { filter: brightness(1.15); }
#todo-add:active { transform: translate(2px, 2px); }
#todo-add:focus-visible { outline: 3px solid var(--text); outline-offset: 2px; }
.todo-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.todo-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  background: var(--bg);
  border: 2px solid var(--border);
}
.todo-item input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: var(--accent);
  cursor: pointer;
  flex-shrink: 0;
}
.todo-item input[type="checkbox"]:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.todo-text {
  flex: 1;
  word-break: break-word;
  font-size: 1rem;
}
.todo-item.done .todo-text { text-decoration: line-through; color: var(--muted); }
.todo-delete {
  background: transparent;
  border: 2px solid var(--border);
  color: var(--muted);
  width: 32px;
  height: 32px;
  font-size: 1rem;
  cursor: pointer;
  border-radius: 0;
  flex-shrink: 0;
  line-height: 1;
}
.todo-delete:hover { border-color: var(--accent); color: var(--accent); }
.todo-delete:active { transform: translate(1px, 1px); }
.todo-delete:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  border: 0;
}

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const list = document.getElementById('todo-list');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');

let nextId = 1;
const tasks = [];

function updateCounts() {
  totalEl.textContent = String(tasks.length);
  remainingEl.textContent = String(tasks.filter(t => !t.done).length);
}

function renderTask(task) {
  const li = document.createElement('li');
  li.className = 'todo-item' + (task.done ? ' done' : '');
  li.dataset.id = task.id;

  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.id = 'todo-check-' + task.id;
  checkbox.checked = task.done;
  checkbox.setAttribute('aria-label', 'Toggle task: ' + task.text);
  checkbox.addEventListener('change', () => {
    task.done = checkbox.checked;
    li.classList.toggle('done', task.done);
    updateCounts();
  });

  const span = document.createElement('span');
  span.className = 'todo-text';
  span.id = 'todo-text-' + task.id;
  span.textContent = task.text;

  const del = document.createElement('button');
  del.type = 'button';
  del.className = 'todo-delete';
  del.id = 'todo-delete-' + task.id;
  del.textContent = '\u00d7';
  del.setAttribute('aria-label', 'Delete task: ' + task.text);
  del.addEventListener('click', () => {
    const idx = tasks.indexOf(task);
    if (idx !== -1) tasks.splice(idx, 1);
    li.remove();
    updateCounts();
  });

  li.append(checkbox, span, del);
  list.appendChild(li);
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;
  const task = { id: nextId++, text, done: false };
  tasks.push(task);
  renderTask(task);
  input.value = '';
  input.focus();
  updateCounts();
}

addBtn.addEventListener('click', addTask);
input.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') { e.preventDefault(); addTask(); }
});

updateCounts();
